import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
names = data[1:]

from collections import defaultdict, deque

# Create a graph where each node is a character and edges represent the order
graph = defaultdict(list)
in_degree = {chr(i): 0 for i in range(ord('a'), ord('z') + 1)}

# Function to compare two names and add edges to the graph
def compare_names(name1, name2):
    min_len = min(len(name1), len(name2))
    for i in range(min_len):
        if name1[i] != name2[i]:
            if name2[i] not in graph[name1[i]]:
                graph[name1[i]].append(name2[i])
                in_degree[name2[i]] += 1
            break
    else:
        if len(name1) > len(name2):
            return False
    return True

# Compare all pairs of consecutive names
for i in range(n - 1):
    if not compare_names(names[i], names[i + 1]):
        print("Impossible")
        exit()

# Topological sort using Kahn's algorithm
queue = deque([char for char in in_degree if in_degree[char] == 0])
result = []

while queue:
    char = queue.popleft()
    result.append(char)
    for neighbor in graph[char]:
        in_degree[neighbor] -= 1
        if in_degree[neighbor] == 0:
            queue.append(neighbor)

# Check if we have a valid topological sort
if len(result) == 26:
    print(''.join(result))
else:
    print("Impossible")
